    sorted_bids = sorted(yesterday_bids) if yesterday_bids else []
    median_prev_bid = 0.0
    if sorted_bids:
        mid = len(sorted_bids) // 2
        median_prev_bid = float(sorted_bids[mid])

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # If Cindy-style extreme pressure existed yesterday, avoid matching it; still bid enough to beat low bidders.
    # Heuristic thresholds based on observed yesterday: Cindy ~160+, David ~22, Eric ~149.
    extreme_pressure = max_prev_bid >= 150.0
    high_pressure = max_prev_bid >= 120.0

    # Determine target bid
    # - If I'm low HP, I must bid more.
    # - If yesterday showed extreme pressure, bid around (median + margin) rather than max.
    # - Otherwise, bid around median or a supply-adjusted mid.
    if my_hp <= 2.0:
        base = max(median_prev_bid + 10.0, DAILY_SALARY * 0.85)
    elif my_hp <= 4.0:
        base = max(median_prev_bid + 7.0, DAILY_SALARY * 0.65)
    else:
        if extreme_pressure:
            # Cindy likely spends to survive; don't chase max. Beat the low/medium bidders.
            base = max(median_prev_bid + 5.0, DAILY_SALARY * (0.45 + 0.15 * supply_band))
        elif high_pressure:
            base = max(median_prev_bid + 3.0, DAILY_SALARY * (0.55 + 0.10 * supply_band))
        else:
            base = max(median_prev_bid, DAILY_SALARY * (0.40 + 0.10 * supply_band))

    # Cap by budget and also avoid overspending beyond what supply suggests
    # Supply suggests how many batches might exist; translate to a soft cap.
    # When supply is higher, we can bid slightly less.
    # batches ~ supply/WATER_REQ
    batches = supply / float(WATER_REQ) if WATER_REQ > 0 else 1.0
    # soft cap factor: more batches => lower cap
    cap_factor = 1.0
    if batches >= 2.0:
        cap_factor = 0.9
    elif batches <= 1.2:
        cap_factor = 1.05

    bid = base * cap_factor

    # Final constraints
    if my_budget <= 0.0:
        return 0.0
    bid = min(bid, my_budget)

    # Ensure non-negative float
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_DAYS = 10

    my_water_value = DAILY_SALARY / WATER_REQ

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    opponent_water_values = []
    total_opponent_water_req = 0

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

        opp_water_req = opp.get('water_requirement', 1)
        opp_daily_salary = opp.get('daily_salary', 0)
        if opp_water_req > 0:
            opponent_water_values.append(opp_daily_salary / opp_water_req)

        total_opponent_water_req += opp_water_req

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    max_opponent_value = max(opponent_water_values) if opponent_water_values else 0.0

    competitive_floor = max(my_water_value, max_opponent_value * 0.8) if max_opponent_value > 0 else my_water_value

    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        bid = DAILY_SALARY * 0.95
    else:
        base_bid = my_water_value

        if highest_prev_bid > 0:
            if highest_prev_bid > competitive_floor * 1.5:
                if my_status['hp'] > 5:
                    base_bid = max(base_bid, competitive_floor * 1.1)
                else:
                    base_bid = max(base_bid, highest_prev_bid * 0.8)
            else:
                base_bid = max(base_bid, highest_prev_bid + 0.5)

        total_water_needed = WATER_REQ + total_opponent_water_req
        current_supply = day_context['supply']

        if current_supply < total_water_needed * 1.2:
            base_bid *= 1.1
        elif current_supply > total_water_needed * 1.5:
            base_bid *= 0.9

        days_remaining = MAX_DAYS - day_context['day']
        if days_remaining <= 2:
            base_bid *= 1.15
        elif day_context['day'] <= 2:
            base_bid *= 0.9

        bid = base_bid

    final_bid = max(1.0, min(my_status['budget'], bid))

    return final_bid

